        "temperature": "30 °C (standard for kinase assays)"
      }
    },
    {
      "card_id": "kinase-detect",
      "instruction": "Terminate the kinase reaction, deplete remaining ATP with the ADP‑Glo reagent, then add the detection reagent and read luminescence.",
      "parameters": {
        "reagent_volumes": "20 µL detection reagent per 20 µL reaction (per kit protocol)",
        "depletion_time": "40 min (per ADP‑Glo kit)",
        "detection_time": "10 min (luminescence stabilization)"
      }
    },
