      "card_id": "analyse",
      "instruction": "Normalize luminescence to 0 % activity (no‑enzyme control) and 100 % activity (vehicle control), fit a four‑parameter logistic curve, report IC50 with 95 % confidence interval, and note assay performance metrics (Z′‑factor).",
      "parameters": {
        "fit_model": "4‑parameter logistic (Hill slope unconstrained)",
        "acceptance_criteria": "Z′‑factor ≥ 0.5; curve R² ≥ 0.9; top/bottom asymptotes within 10 % of controls"
      }
